import{_ as r,C as e,o as c,c as i,E as a,a7 as s}from"./chunks/framework.FWlv_suP.js";const g=JSON.parse('{"title":"LocalTell Data Collection","description":"Data collection summary for LocalTell.","frontmatter":{"title":"LocalTell Data Collection","description":"Data collection summary for LocalTell."},"headers":[],"relativePath":"apps/local-tell/data-collection.md","filePath":"apps/local-tell/data-collection.md"}'),d={name:"apps/local-tell/data-collection.md"};function p(h,o,u,m,f,y){const t=e("AppBreadcrumbs"),l=e("AppSubnav"),n=e("CopyStandaloneUrl");return c(),i("div",null,[a(t,{"app-id":"local-tell",current:"Data Collection"}),a(l,{"app-id":"local-tell"}),a(n,{path:"/data-collection/local-tell",label:"Copy standalone data collection URL","copied-label":"Data collection URL copied","document-name":"LocalTell data collection page"}),o[0]||(o[0]=s('<h1 id="localtell-data-collection" tabindex="-1">LocalTell Data Collection <a class="header-anchor" href="#localtell-data-collection" aria-label="Permalink to &quot;LocalTell Data Collection&quot;">​</a></h1><p><strong>Last reviewed:</strong> September 24, 2026</p><h2 id="on-device-processing" tabindex="-1">On-device processing <a class="header-anchor" href="#on-device-processing" aria-label="Permalink to &quot;On-device processing&quot;">​</a></h2><p>With Android location permission, LocalTell reads serving-cell identifiers, including radio technology, MCC/MNC, area code, cell ID, and signal strength. It processes these identifiers on the device to find an approximate locality in a locally installed offline SQLite pack. LocalTell does not request or read GPS coordinates.</p><p>Optional Journey mode stores local entries containing the time, approximate area, optional district/state, radio, network code, cell ID, and confidence. Installed-pack metadata and preferences are also stored locally.</p><h2 id="data-received-by-the-developer" tabindex="-1">Data received by the developer <a class="header-anchor" href="#data-received-by-the-developer" aria-label="Permalink to &quot;Data received by the developer&quot;">​</a></h2><p>LocalTell has no account, analytics, advertising, crash reporting, tracking, or developer-operated cloud database. The developer does not receive serving-cell information, approximate-area results, downloaded-pack contents, or Journey history. Support email contains only what you choose to send.</p><h2 id="optional-transfers" tabindex="-1">Optional transfers <a class="header-anchor" href="#optional-transfers" aria-label="Permalink to &quot;Optional transfers&quot;">​</a></h2><p>The app downloads only the offline packs you select and checks for updates over HTTPS. If you choose Share, the selected Android share target receives the approximate-area text you choose to share. Those external destinations apply their own privacy practices.</p><h2 id="google-play-data-safety-context" tabindex="-1">Google Play Data safety context <a class="header-anchor" href="#google-play-data-safety-context" aria-label="Permalink to &quot;Google Play Data safety context&quot;">​</a></h2><p>LocalTell&#39;s serving-cell processing and Journey records remain on the device and are not transmitted to the developer. Play Console declarations must be reviewed for every release and for any future feature that changes these data practices.</p>',11))])}const _=r(d,[["render",p]]);export{g as __pageData,_ as default};
